INSERT INTO "announcements" ("id", "title", "body", "author_id", "pinned", "created_at") VALUES (1, 'Diwali collection launch', 'Our festive collection goes live on the website on Friday. Store teams: please review the new pieces in the vault before then.', 1, 1, 1791526836000);
INSERT INTO "announcements" ("id", "title", "body", "author_id", "pinned", "created_at") VALUES (2, 'New leave policy', 'Earned leave allowance increases from 12 to 15 days from this year. See the Leave Policy for details.', 4, 0, 1790827426000);
INSERT INTO "announcements" ("id", "title", "body", "author_id", "pinned", "created_at") VALUES (3, 'Welcome Divya!', 'Divya Hegde joins our marketing team as Content Marketer. Say hello!', 4, 0, 1791131233000);
INSERT INTO "jobs" ("id", "slug", "title", "department", "location", "type", "description", "requirements", "open", "created_at") VALUES (1, 'senior-jewellery-designer', 'Senior Jewellery Designer', 'Design', 'Mangaluru', 'full_time', 'Lead design for our bridal and high-jewellery lines, from hand sketches to CAD-ready drawings, working closely with our karigars.', '["5+ years designing fine jewellery","Strong hand-sketching and Rhino/Matrix CAD","Understanding of stone setting and casting","A portfolio we can see"]', 1, 1791835550696);
INSERT INTO "jobs" ("id", "slug", "title", "department", "location", "type", "description", "requirements", "open", "created_at") VALUES (2, 'retail-jewellery-consultant', 'Retail Jewellery Consultant', 'Sales', 'Bengaluru', 'full_time', 'Guide customers through one of the biggest purchases of their lives. You will run consultations, manage appointments and follow up after the sale.', '["2+ years in luxury retail","Fluent English and Kannada; Hindi is a plus","Comfort with high-value transactions"]', 1, 1791835550696);
INSERT INTO "jobs" ("id", "slug", "title", "department", "location", "type", "description", "requirements", "open", "created_at") VALUES (3, 'digital-marketing-associate', 'Digital Marketing Associate', 'Marketing', 'Remote (India)', 'full_time', 'Plan and run our performance campaigns and email programme, and report on what is working.', '["2+ years running Meta and Google campaigns","Comfortable with analytics","Great written English"]', 1, 1791835550696);
INSERT INTO "jobs" ("id", "slug", "title", "department", "location", "type", "description", "requirements", "open", "created_at") VALUES (4, 'gemology-intern', 'Gemology Intern', 'Quality', 'Mangaluru', 'internship', 'A six-month internship grading and documenting coloured stones and diamonds alongside our quality lead.', '["Pursuing or completed a gemology diploma (GIA/IGI)","Attention to detail"]', 1, 1791835550696);
INSERT INTO "jobs" ("id", "slug", "title", "department", "location", "type", "description", "requirements", "open", "created_at") VALUES (5, 'delivery-partner', 'Delivery Partner', 'Logistics', 'Mangaluru', 'contract', 'Deliver insured parcels across Dakshina Kannada and Udupi with our secure OTP handover process.', '["Two-wheeler and valid licence","Smartphone","Clean background check"]', 1, 1791835550696);
