INSERT INTO "policies" ("id", "title", "category", "body", "updated_at") VALUES (1, 'Leave policy', 'Time off', 'Every employee receives 12 casual, 10 sick and 15 earned leave days per calendar year. Leave is requested in the employee portal and approved by your manager. Unpaid leave is available on approval and is deducted pro-rata in payroll. Sundays are not counted.', 1791835550696);
INSERT INTO "policies" ("id", "title", "category", "body", "updated_at") VALUES (2, 'Code of conduct', 'Conduct', 'Treat every customer and colleague with respect. Never share customer details outside the company. Report any gift or payment from suppliers to HR.', 1791835550696);
INSERT INTO "policies" ("id", "title", "category", "body", "updated_at") VALUES (3, 'Vault & security procedure', 'Operations', 'The vault is opened by two authorised staff together. Every piece taken out for display or a customer is logged in inventory. Daily counts are reconciled by the inventory executive before closing.', 1791835550696);
INSERT INTO "policies" ("id", "title", "category", "body", "updated_at") VALUES (4, 'Payroll & reimbursements', 'Payroll', 'Salaries are processed on the last working day of the month. Payslips are available in the HR portal. Reimbursement claims must be submitted with receipts within 30 days.', 1791835550696);
INSERT INTO "settings" ("key", "value", "updated_at") VALUES ('maintenance', '{"enabled":false,"message":"We are polishing things up. Back shortly!"}', 1791835550698);
